// signed cookies (cookies secret: :secret_key, format :hmac): written by the compiler
fn axum_dsl_cookie_key() -> &'static [u8] {
    settings().secret_key.as_bytes()
}

fn axum_dsl_cookie_mac(secret: &[u8], name: &str, value: &str) -> Option<::hmac::Hmac<::sha2::Sha256>> {
    use ::hmac::Mac;
    let mut mac = ::hmac::Hmac::<::sha2::Sha256>::new_from_slice(secret).ok()?;
    mac.update(name.as_bytes());
    mac.update(b"=");
    mac.update(value.as_bytes());
    Some(mac)
}

fn axum_dsl_cookie_sign(secret: &[u8], name: &str, value: &str) -> String {
    use ::base64::Engine;
    use ::hmac::Mac;
    let url = ::base64::engine::general_purpose::URL_SAFE_NO_PAD;
    let tag = match axum_dsl_cookie_mac(secret, name, value) {
        Some(mac) => mac.finalize().into_bytes(),
        None => return String::new(),
    };
    format!("{}.{}", url.encode(value), url.encode(tag))
}

fn axum_dsl_cookie_verify(secret: &[u8], name: &str, signed: &str) -> Option<String> {
    use ::base64::Engine;
    use ::hmac::Mac;
    let url = ::base64::engine::general_purpose::URL_SAFE_NO_PAD;
    let (value_part, tag_part) = signed.split_once('.')?;
    let value = String::from_utf8(url.decode(value_part).ok()?).ok()?;
    let tag = url.decode(tag_part).ok()?;
    axum_dsl_cookie_mac(secret, name, &value)?.verify_slice(&tag).ok()?;
    Some(value)
}

fn axum_dsl_cookie(headers: &::axum::http::HeaderMap, name: &str) -> Option<String> {
    for line in headers.get_all(::axum::http::header::COOKIE) {
        let Ok(line) = line.to_str() else { continue };
        for pair in line.split(';') {
            if let Some((key, signed)) = pair.trim().split_once('=') {
                if key == name {
                    if let Some(value) = axum_dsl_cookie_verify(axum_dsl_cookie_key(), name, signed) {
                        return Some(value);
                    }
                }
            }
        }
    }
    None
}

fn axum_dsl_set_cookie(name: &str, value: &str, http_only: bool, same_site: &str, secure: bool, max_age: Option<i64>) -> String {
    let mut line = format!("{}={}; Path=/", name, axum_dsl_cookie_sign(axum_dsl_cookie_key(), name, value));
    if let Some(seconds) = max_age {
        line.push_str(&format!("; Max-Age={seconds}"));
    }
    line.push_str(&format!("; SameSite={same_site}"));
    if http_only {
        line.push_str("; HttpOnly");
    }
    if secure {
        line.push_str("; Secure");
    }
    line
}

fn axum_dsl_delete_cookie(name: &str) -> String {
    format!("{name}=; Path=/; Max-Age=0")
}

fn axum_dsl_apply_cookies(response: &mut ::axum::response::Response, cookies: &[String]) {
    for cookie in cookies {
        if let Ok(value) = ::axum::http::HeaderValue::from_str(cookie) {
            response.headers_mut().append(::axum::http::header::SET_COOKIE, value);
        }
    }
}

// sessions runtime (random_token, request_ip, request_base_url, user_agent, Bcrypt, the current and filter helpers): written by the compiler
fn axum_dsl_random_token() -> String {
    use ::rand::Rng;
    const ALPHABET: &[u8] = b"123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
    let mut rng = ::rand::rng();
    (0..24)
        .map(|_| char::from(ALPHABET.get(rng.random_range(0..ALPHABET.len())).copied().unwrap_or(b'1')))
        .collect()
}

fn axum_dsl_request_ip(_headers: &::axum::http::HeaderMap, peer: Option<::std::net::SocketAddr>) -> String {
    peer.map(|addr| addr.ip().to_string()).unwrap_or_default()
}

fn axum_dsl_request_base_url(headers: &::axum::http::HeaderMap) -> String {
    match headers.get("host").and_then(|value| value.to_str().ok()).map(|entry| entry.trim()).filter(|entry| !entry.is_empty()) {
        Some(host) => format!("http://{}", host),
        None => String::new(),
    }
}

fn axum_dsl_user_agent(headers: &::axum::http::HeaderMap) -> String {
    headers
        .get(::axum::http::header::USER_AGENT)
        .and_then(|value| value.to_str().ok())
        .unwrap_or_default()
        .to_string()
}

async fn axum_dsl_bcrypt_verify(plain: String, digest: String) -> bool {
    ::tokio::task::spawn_blocking(move || ::bcrypt::verify(plain, &digest).unwrap_or(false))
        .await
        .unwrap_or(false)
}

async fn axum_dsl_bcrypt_hash(plain: String) -> Result<String, String> {
    ::tokio::task::spawn_blocking(move || ::bcrypt::hash(plain, 12).map_err(|e| format!("error: Bcrypt.hash failed: {e}")))
        .await
        .map_err(|e| format!("error: Bcrypt.hash failed: {e}"))?
}

async fn axum_dsl_fetch_metadata(request: ::axum::extract::Request, next: ::axum::middleware::Next) -> ::axum::response::Response {
    let method = request.method();
    let reads = *method == ::axum::http::Method::GET || *method == ::axum::http::Method::HEAD || *method == ::axum::http::Method::OPTIONS;
    let cross_site = matches!(
        request.headers().get("sec-fetch-site"),
        Some(site) if site.as_bytes() != b"same-origin" && site.as_bytes() != b"none"
    );
    if !reads && cross_site {
        let mut refused = ::axum::response::IntoResponse::into_response("cross-site request refused");
        *refused.status_mut() = ::axum::http::StatusCode::FORBIDDEN;
        return refused;
    }
    next.run(request).await
}

// use_layer :rate_limit: one fixed window of requests per client address: written by the compiler
const AXUM_DSL_RATE_LIMIT_PER: u64 = 60;
const AXUM_DSL_RATE_LIMIT_BURST: u32 = 25;
const AXUM_DSL_RATE_LIMIT_PATH: &str = "/session";
static AXUM_DSL_RATE_LIMIT: ::std::sync::OnceLock<::std::sync::Mutex<::std::collections::HashMap<String, (u64, u32)>>> =
    ::std::sync::OnceLock::new();

async fn axum_dsl_rate_limit(request: ::axum::extract::Request, next: ::axum::middleware::Next) -> ::axum::response::Response {
    if !AXUM_DSL_RATE_LIMIT_PATH.is_empty() && request.uri().path() != AXUM_DSL_RATE_LIMIT_PATH {
        return next.run(request).await;
    }
    let peer = request.extensions().get::<::axum::extract::ConnectInfo<::std::net::SocketAddr>>().map(|info| info.0);
    let client = axum_dsl_request_ip(request.headers(), peer);
    let now = ::std::time::SystemTime::now()
        .duration_since(::std::time::UNIX_EPOCH)
        .map(|elapsed| elapsed.as_secs())
        .unwrap_or(0);
    let window = now / AXUM_DSL_RATE_LIMIT_PER;
    let over = {
        let cells = AXUM_DSL_RATE_LIMIT.get_or_init(|| ::std::sync::Mutex::new(::std::collections::HashMap::new()));
        let mut counts = match cells.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        };
        let entry = counts.entry(client).or_insert((window, 0));
        if entry.0 != window {
            *entry = (window, 0);
        }
        entry.1 = entry.1.saturating_add(1);
        entry.1 > AXUM_DSL_RATE_LIMIT_BURST
    };
    if over {
        let mut refused = ::axum::response::IntoResponse::into_response("rate limit exceeded");
        *refused.status_mut() = ::axum::http::StatusCode::TOO_MANY_REQUESTS;
        return refused;
    }
    next.run(request).await
}

// the per-request values of `current`: each is computed on its first read and kept for the request: written by the compiler
#[derive(Default)]
struct AxumDslCurrents {
    user: ::tokio::sync::OnceCell<Option<User>>,
}

async fn axum_dsl_current_scope(mut request: ::axum::extract::Request, next: ::axum::middleware::Next) -> ::axum::response::Response {
    request.extensions_mut().insert(::std::sync::Arc::new(AxumDslCurrents::default()));
    next.run(request).await
}

async fn axum_dsl_current_user(__headers: &::axum::http::HeaderMap, __peer: Option<::std::net::SocketAddr>, __currents: &AxumDslCurrents) -> Result<Option<User>, String> {
    let token = axum_dsl_cookie(&__headers, "session_token");
    Ok(match token { None => { None }, Some(token) => { query_user_for_session(token.clone()).await? } })
}

fn internal_error(message: &str) -> ::axum::response::Response {
    let mut response = ::axum::response::IntoResponse::into_response(message.to_string());
    *response.status_mut() = ::axum::http::StatusCode::INTERNAL_SERVER_ERROR;
    response
}

fn error_response(message: &str) -> ::axum::response::Response {
    internal_error(message)
}

async fn route_1() -> ::axum::response::Response {
    let response = ::axum::response::IntoResponse::into_response(::axum::response::Html("<form method='post' action='/session'><input name='email'><input name='password' type='password'><button>Log in</button></form>".to_string()));
    response
}

#[allow(unused_variables)]
async fn route_2(__headers: ::axum::http::HeaderMap, axum::extract::Form(__form): axum::extract::Form<Signup>) -> ::axum::response::Response {
    let Signup { name, email, password } = __form;
    let response = match (async || -> Result<::axum::response::Response, String> {
        if !query_user_by_email(email.clone()).await?.is_none() { return Ok({ let mut __halted = ::axum::response::IntoResponse::into_response("that email address is taken".to_string()); *__halted.status_mut() = ::axum::http::StatusCode::from_u16(409).unwrap(); __halted }); }
        let added = query_add_user(name.clone(), email.clone(), axum_dsl_bcrypt_hash(password.clone()).await?.clone()).await?;
        if added != 1 { return Ok({ let mut __halted = ::axum::response::IntoResponse::into_response("the user was not added".to_string()); *__halted.status_mut() = ::axum::http::StatusCode::from_u16(500).unwrap(); __halted }); }
        Ok({ let mut __redirect = ::axum::response::IntoResponse::into_response((::axum::http::StatusCode::FOUND, ())); let __location = format!("{}{}", axum_dsl_request_base_url(&__headers), "/session/new"); __redirect.headers_mut().insert(::axum::http::header::LOCATION, ::axum::http::HeaderValue::from_str(&__location).expect("a redirect path must be a valid header value")); __redirect.headers_mut().insert(::axum::http::header::CONTENT_TYPE, ::axum::http::HeaderValue::from_static("text/html; charset=utf-8")); __redirect })
    })().await {
        Ok(response) => response,
        Err(message) => error_response(&message),
    };
    response
}

#[allow(unused_variables)]
async fn route_3(__headers: ::axum::http::HeaderMap, ::axum::extract::ConnectInfo(__connect): ::axum::extract::ConnectInfo<::std::net::SocketAddr>, axum::extract::Form(__form): axum::extract::Form<Login>) -> ::axum::response::Response {
    let __peer = Some(__connect);
    let mut __cookies: Vec<String> = Vec::new();
    let Login { email, password } = __form;
    let response = match (async || -> Result<::axum::response::Response, String> {
        let user = query_user_by_email(email.clone()).await?;
        if match user.clone() { None => true, Some(user) => !axum_dsl_bcrypt_verify(password.clone(), user.password_digest.clone().clone()).await } { return Ok({ let mut __halted = ::axum::response::IntoResponse::into_response("bad login".to_string()); *__halted.status_mut() = ::axum::http::StatusCode::from_u16(401).unwrap(); __halted }); } let user = match user { Some(__v) => __v, None => return Ok({ let mut __halted = ::axum::response::IntoResponse::into_response("bad login".to_string()); *__halted.status_mut() = ::axum::http::StatusCode::from_u16(401).unwrap(); __halted }) };
        let token = axum_dsl_random_token();
        let started = query_start_session(token.clone(), user.id, axum_dsl_request_ip(&__headers, __peer).clone(), axum_dsl_user_agent(&__headers).clone()).await?;
        if started != 1 { return Ok({ let mut __halted = ::axum::response::IntoResponse::into_response("the session was not started".to_string()); *__halted.status_mut() = ::axum::http::StatusCode::from_u16(500).unwrap(); __halted }); }
        __cookies.push(axum_dsl_set_cookie("session_token", &token, true, "Lax", false, Some(631139040)));
        Ok({ let mut __stated = { let mut __redirect = ::axum::response::IntoResponse::into_response((::axum::http::StatusCode::FOUND, ())); let __location = format!("{}{}", axum_dsl_request_base_url(&__headers), "/me"); __redirect.headers_mut().insert(::axum::http::header::LOCATION, ::axum::http::HeaderValue::from_str(&__location).expect("a redirect path must be a valid header value")); __redirect.headers_mut().insert(::axum::http::header::CONTENT_TYPE, ::axum::http::HeaderValue::from_static("text/html; charset=utf-8")); __redirect };
    __stated })
    })().await {
        Ok(mut response) => { axum_dsl_apply_cookies(&mut response, &__cookies); response }
        Err(message) => error_response(&message),
    };
    response
}

async fn route_4(__headers: ::axum::http::HeaderMap, ::axum::extract::ConnectInfo(__connect): ::axum::extract::ConnectInfo<::std::net::SocketAddr>, ::axum::Extension(__currents): ::axum::Extension<::std::sync::Arc<AxumDslCurrents>>) -> ::axum::response::Response {
    let __peer = Some(__connect);
    let response = match (async || -> Result<::axum::response::Response, String> {
        let user = __currents.user.get_or_try_init(|| axum_dsl_current_user(&__headers, __peer, &__currents)).await?.clone();
        let user = match user { Some(__v) => __v, None => return Ok({ let mut __redirect = ::axum::response::IntoResponse::into_response((::axum::http::StatusCode::FOUND, ())); let __location = format!("{}{}", axum_dsl_request_base_url(&__headers), "/session/new"); __redirect.headers_mut().insert(::axum::http::header::LOCATION, ::axum::http::HeaderValue::from_str(&__location).expect("a redirect path must be a valid header value")); __redirect.headers_mut().insert(::axum::http::header::CONTENT_TYPE, ::axum::http::HeaderValue::from_static("text/html; charset=utf-8")); __redirect }) };
        Ok(::axum::response::IntoResponse::into_response(format!("Hello, {}", user.name.clone())))
    })().await {
        Ok(response) => response,
        Err(message) => error_response(&message),
    };
    response
}

async fn route_5(__headers: ::axum::http::HeaderMap) -> ::axum::response::Response {
    let mut __cookies: Vec<String> = Vec::new();
    let response = match (async || -> Result<::axum::response::Response, String> {
        let token = axum_dsl_cookie(&__headers, "session_token");
        let token = match token { Some(__v) => __v, None => return Ok({ let mut __redirect = ::axum::response::IntoResponse::into_response((::axum::http::StatusCode::FOUND, ())); let __location = format!("{}{}", axum_dsl_request_base_url(&__headers), "/session/new"); __redirect.headers_mut().insert(::axum::http::header::LOCATION, ::axum::http::HeaderValue::from_str(&__location).expect("a redirect path must be a valid header value")); __redirect.headers_mut().insert(::axum::http::header::CONTENT_TYPE, ::axum::http::HeaderValue::from_static("text/html; charset=utf-8")); __redirect }) };
        let ended = query_end_session(token.clone()).await?;
        __cookies.push(axum_dsl_delete_cookie("session_token"));
        Ok({ let mut __stated = { let mut __redirect = ::axum::response::IntoResponse::into_response((::axum::http::StatusCode::FOUND, ())); let __location = format!("{}{}", axum_dsl_request_base_url(&__headers), &format!("/session/new?ended={}", ended)); __redirect.headers_mut().insert(::axum::http::header::LOCATION, ::axum::http::HeaderValue::from_str(&__location).expect("a redirect path must be a valid header value")); __redirect.headers_mut().insert(::axum::http::header::CONTENT_TYPE, ::axum::http::HeaderValue::from_static("text/html; charset=utf-8")); __redirect };
    __stated })
    })().await {
        Ok(mut response) => { axum_dsl_apply_cookies(&mut response, &__cookies); response }
        Err(message) => error_response(&message),
    };
    response
}

// Resolves on ctrl-c or SIGTERM, so the server stops taking connections and drains: written by the compiler
async fn shutdown_signal() {
    let ctrl_c = async {
        tokio::signal::ctrl_c().await.expect("cannot listen for ctrl-c");
    };
    #[cfg(unix)]
    let terminate = async {
        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
            .expect("cannot listen for SIGTERM")
            .recv()
            .await;
    };
    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();
    tokio::select! {
        _ = ctrl_c => {}
        _ = terminate => {}
    }
}

// jemalloc as the global allocator, and no transparent huge pages on Linux: written by the compiler
#[global_allocator]
static GLOBAL: tikv_jemallocator::Jemalloc = tikv_jemallocator::Jemalloc;

// jemalloc reads its options from this exported symbol (tikv-jemallocator's `_rjem_` prefix) when it
// starts, before main. It is a `const char *`, so a thin pointer to the first byte.
#[cfg(target_os = "linux")]
#[allow(unsafe_code)]
#[unsafe(export_name = "_rjem_malloc_conf")]
pub static JEMALLOC_CONF: Option<&'static std::ffi::c_char> =
    // SAFETY: points at the first byte of a static, NUL-terminated string.
    Some(unsafe { &*c"thp:never".as_ptr() });

// With transparent huge pages set to `always`, every thread stack gets backed by whole 2 MB pages as
// soon as it is touched; nothing here is big enough to gain from them, so the process opts out.
#[allow(unsafe_code)]
fn disable_transparent_huge_pages() {
    #[cfg(target_os = "linux")]
    {
        let off: libc::c_ulong = 1;
        // SAFETY: PR_SET_THP_DISABLE takes machine-width integer arguments and only changes this
        // process's memory policy.
        if unsafe { libc::prctl(libc::PR_SET_THP_DISABLE, off, 0 as libc::c_ulong, 0 as libc::c_ulong, 0 as libc::c_ulong) } != 0 {
            eprintln!("couldn't disable transparent huge pages: {}", std::io::Error::last_os_error());
        }
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    disable_transparent_huge_pages();
    match load_settings() {
        Ok(loaded) => {
            let _ = SETTINGS.set(loaded);
        }
        Err(message) => {
            eprintln!("{message}");
            std::process::exit(2);
        }
    }
    if settings().secret_key.len() < 32 {
        eprintln!("error: SECRET_KEY_BASE is the key cookies are signed with, and it must be at least 32 bytes");
        std::process::exit(2);
    }
    if let Err(message) = db_open().await {
        eprintln!("{message}");
        std::process::exit(2);
    }
    let router = axum::Router::new()
        .route("/session/new", axum::routing::get(route_1))
        .route("/signup", axum::routing::post(route_2))
        .route("/session", axum::routing::post(route_3))
        .route("/me", axum::routing::get(route_4))
        .route("/session", axum::routing::delete(route_5))
        .layer(axum::middleware::from_fn(axum_dsl_current_scope))
        .layer(::axum::middleware::from_fn(axum_dsl_fetch_metadata))
        .layer(::axum::middleware::from_fn(axum_dsl_rate_limit));
    let port = match std::env::var("PORT") {
        Ok(value) => match value.parse::<u16>() {
            Ok(port) => port,
            Err(_) => {
                eprintln!("PORT must be a port number from 0 to 65535, got {value:?}");
                std::process::exit(2);
            }
        },
        Err(_) => 8086,
    };
    let bind = std::env::var("BIND").unwrap_or_else(|_| "127.0.0.1".to_string());
    let listener = tokio::net::TcpListener::bind((bind.as_str(), port)).await?;
    axum::serve(listener, router.into_make_service_with_connect_info::<std::net::SocketAddr>())
        .with_graceful_shutdown(shutdown_signal())
        .await?;
    Ok(())
}
